const o="Transition payroll - {{dateRange}}",e="Because you changed your pay schedule, you'll need to run some transition payrolls. Transition payrolls let you pay employees for any workdays during gaps between pay schedules. You may choose to skip them, but it is your responsibility to ensure employees are paid properly. Regular payroll functionality is blocked until you either run or skip transition payrolls.",l="Run Transition Payroll",i="Skip this payroll",r="Transition payroll skipped",a={title:"Skip {{dateRange}} transition payroll?",body:"Skipping this payroll means employees will not be paid for the transition period. It is your responsibility to ensure employees are paid properly.",confirmCta:"Skip payroll",cancelCta:"Cancel"},t={alertTitle:o,alertDescription:e,runPayroll:l,skipPayroll:i,skipSuccessAlert:r,skipDialog:a};export{e as alertDescription,o as alertTitle,t as default,l as runPayroll,a as skipDialog,i as skipPayroll,r as skipSuccessAlert};
